// TH18 v1.00a st07.ecl.txt: MainSub02 1224-1236, Cir01 53-76, Cir01_at 78-98.
// Source arrows below point at the original line numbers.
//
// Public-policy omissions: drops/reward config (dropExtra 0059-0060,
// unknown573 0061, ins_574 0062), animation selection (0055-0056),
// sound (0088) and the birth ANIM record itself (0089).  The ANIM record's
// entry displacement (position -= 4 * velocity) is physical and is kept
// below as sh_dist(-10fx) for the source initial speed 2.5.

const TIME_LIMIT: int = 1680;
const OPENING_BUFFER: int = 120;

const TH18_BALL2: int = 432;   // etSprite 0084 type 5 -> TH18_BALL2
const BALL2_COLOR: int = 10;   // etSprite 0084 color 10

// Cir01_at 0078-0098
async sub cir01_at() {
    wait(20);                                  // 0081
    sh_reset(0);                               // 0082 etNew(0)
    sh_sprite(0, TH18_BALL2, BALL2_COLOR);     // 0084
    sh_aim(0, 1);                              // 0083 etAim(0,0): aimed fan
    sh_ring(0, 0);                             // 0083 mode 0 is a fan
    sh_count(0, 2, 1);                         // 0085
    sh_angle(0, 0deg, 10deg);                  // 0086 0.17453292 rad = 10deg
    sh_speed(0, 2.5fx, 0fx);                   // 0087 etSpeed(2.5,1.0); 1 layer uses s0
    sh_dist(0, -10fx);                         // 0089 ANIM: -4 * 2.5px/frame
    for i in 0..20 {                           // 0090-0096: 20 volleys
        sh_fire(0);                            // 0093 etOn(0)
        wait(10);                              // 0094
    }
}

// Cir01 0053-0076
async sub cir01() {
    set_invuln(65535);                         // training shell: source enemy invincible
    set_hurtbox(14fx);                         // 0057 setHurtbox(28,28): 28 * 0.5
    set_hitbox(8fx);                           // 0058 setHitbox(16,16): 16 * 0.5, body kept
    move_vel(0, 90deg, 3.7fx, EASE_LINEAR);    // 0063 moveVel(pi/2, 3.7)
    wait(100);                                 // 0064
    move_vel(60, 90deg, 0fx, EASE_LINEAR);     // 0065 moveVelTime(60,0,pi/2,0)
    spawn cir01_at();                          // 0066 @Cir01_at() async
    wait(200);                                 // 0067
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);   // 0068 moveVel(ANGLE_PLAYER,0)
    move_vel(60, aim_player(), 1fx, EASE_LINEAR);  // 0069 moveVelTime(60,0,ANGLE_PLAYER,1)
    loop { wait(1000); }                       // 0070-0075 Cir01_428/Cir01_448
}

// MainSub02 1224-1236: A=5, both sides every 20 frames, 100-frame schedule.
async sub pattern() {
    wait(OPENING_BUFFER);                      // training-shell opening buffer
    for round in 0..5 {
        _ = spawn_enemy(160fx, -32fx, 300, 0, 1000, 0, cir01);   // 1230
        _ = spawn_enemy(-160fx, -32fx, 300, 0, 1000, 0, cir01);  // 1231
        wait(20);                              // 1232
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
